import{c as t,Q as a,j as n,m as i}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"Managing OIDC clients","description":"Register, edit, and manage OIDC clients in the admin panel.","frontmatter":{"title":"Managing OIDC clients","description":"Register, edit, and manage OIDC clients in the admin panel."},"headers":[],"relativePath":"admin/managing-clients.md","filePath":"admin/managing-clients.md"}'),r={name:"admin/managing-clients.md"};function o(l,e,c,s,d,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<p>OIDC clients are applications that delegate authentication to GateKeeper. Manage them at <code>/admin/clients</code>.</p><h2 id="endpoint-reference" tabindex="-1">Endpoint reference <a class="header-anchor" href="#endpoint-reference" aria-label="Permalink to &quot;Endpoint reference&quot;">​</a></h2><p>The clients page shows a reference table with all URLs you need when configuring an app:</p><table tabindex="0"><thead><tr><th>Field</th><th>URL</th></tr></thead><tbody><tr><td>Discovery</td><td><code>https://auth.example.com/.well-known/openid-configuration</code></td></tr><tr><td>Authorization URL</td><td><code>https://auth.example.com/authorize</code></td></tr><tr><td>Token URL</td><td><code>https://auth.example.com/oauth/token</code></td></tr><tr><td>Userinfo URL</td><td><code>https://auth.example.com/userinfo</code></td></tr><tr><td>Issuer</td><td><code>https://auth.example.com</code></td></tr><tr><td>JWKS URI</td><td><code>https://auth.example.com/keys</code></td></tr></tbody></table><p>Apps that support OIDC discovery only need the discovery URL - they will auto-configure from it.</p><h2 id="registering-a-client" tabindex="-1">Registering a client <a class="header-anchor" href="#registering-a-client" aria-label="Permalink to &quot;Registering a client&quot;">​</a></h2><p>Click <strong>New client</strong> and fill in:</p><ul><li><strong>Display name</strong> - shown in the admin UI and on the login page when users authenticate via this client.</li><li><strong>Icon URL</strong> - optional. Paste a direct image URL (PNG, SVG, etc.). GateKeeper fetches and caches the image server-side immediately on save - icons are never loaded from external servers by users. Browse <a href="https://selfh.st/icons/" target="_blank" rel="noreferrer">selfh.st/icons</a> for a large library of self-hosted app icons.</li><li><strong>Client ID</strong> - a short identifier like <code>grafana</code> or <code>jellyfin-prod</code>. This is public and appears in authorization requests. Lowercase, digits, dashes, and underscores only. Cannot be changed after creation.</li><li><strong>Client secret</strong> - click <strong>Generate</strong> to create a cryptographically random secret, or paste your own. Store it securely - GateKeeper will not show it again after you close the dialog.</li><li><strong>Redirect URIs</strong> - the callback URLs your app sends users to after authentication. One per line. Must match exactly, including path and scheme.</li></ul><h2 id="editing-a-client" tabindex="-1">Editing a client <a class="header-anchor" href="#editing-a-client" aria-label="Permalink to &quot;Editing a client&quot;">​</a></h2><p>Click the pencil icon on any client row. You can change:</p><ul><li>Display name</li><li>Icon URL (GateKeeper re-fetches and re-caches the image on save)</li><li>Redirect URIs</li><li>Client secret (leave blank to keep the current one; click <strong>Generate</strong> to rotate)</li></ul><p>The client ID cannot be changed.</p><h2 id="redirect-uri-requirements" tabindex="-1">Redirect URI requirements <a class="header-anchor" href="#redirect-uri-requirements" aria-label="Permalink to &quot;Redirect URI requirements&quot;">​</a></h2><p>URIs must match exactly. <code>https://app.example.com/callback</code> and <code>https://app.example.com/callback?extra=param</code> are different URIs.</p><p>Use HTTPS for all production redirect URIs. <code>http://localhost</code> is acceptable for local development only.</p><h2 id="deleting-a-client" tabindex="-1">Deleting a client <a class="header-anchor" href="#deleting-a-client" aria-label="Permalink to &quot;Deleting a client&quot;">​</a></h2><p>Click the trash icon on any client row. This immediately revokes the client&#39;s ability to authenticate. Existing tokens expire naturally according to their TTL (15 minutes for access tokens, 30 days for refresh tokens).</p><h2 id="login-page-branding" tabindex="-1">Login page branding <a class="header-anchor" href="#login-page-branding" aria-label="Permalink to &quot;Login page branding&quot;">​</a></h2><p>When a user is sent to GateKeeper from an OIDC client, the login page automatically shows:</p><ul><li>The client&#39;s display name in the heading (&quot;Sign in to Grafana&quot;)</li><li>The client&#39;s cached icon above the heading</li></ul><p>This only works when the user arrives via the <code>/authorize</code> endpoint (i.e., through the standard OIDC flow). Direct <code>/login</code> access shows the GateKeeper logo.</p>',21)])])}const u=t(r,[["render",o]]);export{g as __pageData,u as default};
